package com.gitlab.seabeam.controlplane.schematic.services.kernel.cluster;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Reads boundary metadata from registry.json (generated by tacplus) and provides
 * the same lookup that the kernel needs for Hazelcast map stats enrichment.
 *
 * <p>Replaces the generated Registry.java class with a runtime-loaded alternative,
 * keeping boundary metadata in the cross-language registry.json rather than
 * hardcoding it in a Java-specific generator.
 */
public class RegistryReader {

	/**
	 * Describes a state boundary — same fields as the former generated Registry.BoundaryInfo.
	 */
	public record BoundaryInfo(
			String service,
			String stateRoot,
			String boundary,
			String consistency,
			// The registry's (spec.persistence) flag, carried verbatim for admin
			// reporting. On a kernel boundary it marks membership in the identity
			// snapshot; kernel does no other durability.
			boolean persistence,
			boolean collection,
			String typeFqn,
			boolean isConfig,
			String graphType,
			List<String> rpcs) {
	}

	private final Map<String, BoundaryInfo> byShortName;

	private RegistryReader(Map<String, BoundaryInfo> byShortName) {
		this.byShortName = Collections.unmodifiableMap(byShortName);
	}

	/**
	 * Looks up a boundary by its short name
	 * (e.g. "services.kernel.Cluster.ClusterInfo").
	 * Returns null if not found.
	 */
	public BoundaryInfo lookupByShortName(String shortName) {
		return byShortName.get(shortName);
	}

	/**
	 * Loads registry.json from the classpath (expects /registry.json at root).
	 */
	public static RegistryReader loadFromClasspath() throws IOException {
		try (InputStream is = RegistryReader.class.getResourceAsStream("/registry.json")) {
			if (is == null) {
				throw new IOException("registry.json not found on classpath");
			}
			return load(is);
		}
	}

	/**
	 * Loads registry.json from the given input stream.
	 */
	public static RegistryReader load(InputStream is) throws IOException {
		JsonObject root;
		try (var reader = new InputStreamReader(is, StandardCharsets.UTF_8)) {
			root = JsonParser.parseReader(reader).getAsJsonObject();
		}
		Map<String, BoundaryInfo> map = new LinkedHashMap<>();
		walkNode(root, map);
		return new RegistryReader(map);
	}

	/**
	 * Recursively walks the registry.json tree, collecting boundary entries.
	 * Each node may have "children" (sub-packages) and "boundaries" (state boundaries).
	 */
	private static void walkNode(JsonObject node, Map<String, BoundaryInfo> map) {
		String fullPath = getString(node, "full_path", "");

		if (node.has("boundaries")) {
			JsonArray boundaries = node.getAsJsonArray("boundaries");
			for (JsonElement elem : boundaries) {
				if (!elem.isJsonObject()) continue;
				JsonObject b = elem.getAsJsonObject();

				String stateRoot = getString(b, "state_root", "");
				String boundary = getString(b, "boundary", "");

				// Build service path: "full_path/state_root"
				String service = fullPath.isEmpty() ? stateRoot : fullPath + "/" + stateRoot;

				// Build short name key: "services.kernel.Cluster.ClusterInfo"
				// The boundary field in registry.json is snake_case; convert to PascalCase.
				String boundaryPascal = toPascalCase(boundary);
				String key = service.replace('/', '.') + "." + boundaryPascal;

				// Parse consistency: "CONSISTENCY_CONVERGENT" → "convergent"
				String rawConsistency = getString(b, "consistency", "");
				String consistency = rawConsistency.startsWith("CONSISTENCY_")
						? rawConsistency.substring("CONSISTENCY_".length()).toLowerCase()
						: rawConsistency.toLowerCase();

				List<String> rpcs = new ArrayList<>();
				if (b.has("rpcs")) {
					for (JsonElement r : b.getAsJsonArray("rpcs")) {
						rpcs.add(r.getAsString());
					}
				}

				map.put(key, new BoundaryInfo(
						service,
						stateRoot,
						boundaryPascal,
						consistency,
						getBoolean(b, "persistence"),
						getBoolean(b, "collection"),
						getString(b, "type_fqn", ""),
						getBoolean(b, "is_config"),
						getString(b, "graph_type", ""),
						Collections.unmodifiableList(rpcs)));
			}
		}

		if (node.has("children")) {
			for (JsonElement child : node.getAsJsonArray("children")) {
				if (child.isJsonObject()) {
					walkNode(child.getAsJsonObject(), map);
				}
			}
		}
	}

	private static String getString(JsonObject obj, String key, String defaultValue) {
		JsonElement e = obj.get(key);
		return (e != null && !e.isJsonNull()) ? e.getAsString() : defaultValue;
	}

	private static boolean getBoolean(JsonObject obj, String key) {
		JsonElement e = obj.get(key);
		return e != null && !e.isJsonNull() && e.getAsBoolean();
	}

	/**
	 * Converts a snake_case string to PascalCase.
	 * "cluster_info" → "ClusterInfo"
	 */
	private static String toPascalCase(String snake) {
		if (snake == null || snake.isEmpty()) return snake;
		StringBuilder sb = new StringBuilder(snake.length());
		boolean capitalizeNext = true;
		for (int i = 0; i < snake.length(); i++) {
			char c = snake.charAt(i);
			if (c == '_') {
				capitalizeNext = true;
			} else if (capitalizeNext) {
				sb.append(Character.toUpperCase(c));
				capitalizeNext = false;
			} else {
				sb.append(c);
			}
		}
		return sb.toString();
	}
}
